func TestSweepBudgetIsSharedAcrossRoots(t *testing.T) {
	repo := t.TempDir()
	t.Setenv(sweepDirBudgetEnv, "64")
	writeFile(t, repo, "src/app.go", "package app\n")
	roots := make([]string, 0, 9)
	for i := 0; i < 8; i++ {
