function New-SampleError {
    param(
        [Parameter(Mandatory)]
        [string] $Section,

        [Parameter(Mandatory)]
        [System.Management.Automation.ErrorRecord] $ErrorRecord
    )

    return [ordered]@{
        section = $Section
