        end_time, _ = state.effective_end()
        duration, source = state.duration()
        parent_name = state.name.rsplit("/", 1)[0]
        return {
            "name": state.name,
            "relative_name": state.name[len(top_name) + 1 :],
            "parent": parent_name,
            "status": state.status or "incomplete",
