#!/usr/bin/env python3
"""Deterministically partition compiled Go tests into weighted execution shards."""

from __future__ import annotations

import argparse
import json
import math
import re
import statistics
import sys
from collections import defaultdict
from pathlib import Path
from typing import Any, Iterable


SCHEMA = "ci-bench.test-shard-plan.v1"
INVENTORY_SCHEMA = "ci-bench.compiled-test-inventory.v1"
_TERMINAL_ACTIONS = frozenset({"pass", "fail", "skip"})


def _read_json(path: Path) -> Any:
    try:
        with path.open(encoding="utf-8-sig") as handle:
            return json.load(handle)
    except (OSError, json.JSONDecodeError) as error:
        raise ValueError(f"cannot read JSON {path}: {error}") from error


def load_inventories(paths: Iterable[Path]) -> list[dict[str, Any]]:
    inventories: list[dict[str, Any]] = []
    seen_packages: set[str] = set()
    for path in paths:
        payload = _read_json(path)
        if payload.get("schema") != INVENTORY_SCHEMA:
            raise ValueError(
                f"{path}: schema is {payload.get('schema')!r}, want {INVENTORY_SCHEMA!r}"
            )
        package = payload.get("importPath")
        tests = payload.get("tests")
        if not isinstance(package, str) or not package:
            raise ValueError(f"{path}: importPath must be a non-empty string")
        if package in seen_packages:
            raise ValueError(f"duplicate package inventory: {package}")
        if not isinstance(tests, list) or not tests:
            raise ValueError(f"{path}: tests must be a non-empty list")
        if any(not isinstance(name, str) or not re.fullmatch(r"Test\w+", name) for name in tests):
            raise ValueError(f"{path}: every test must be a top-level Go Test identifier")
        if len(tests) != len(set(tests)):
            raise ValueError(f"{path}: duplicate test names")
        binary_name = payload.get("binaryName")
        package_relative = payload.get("packageDirectoryRelative")
        if not isinstance(binary_name, str) or Path(binary_name).name != binary_name:
            raise ValueError(f"{path}: binaryName must be a file name")
        if not isinstance(package_relative, str) or not package_relative:
            raise ValueError(f"{path}: packageDirectoryRelative must be non-empty")
        if Path(package_relative).is_absolute() or ".." in Path(package_relative).parts:
            raise ValueError(f"{path}: unsafe packageDirectoryRelative")
        seen_packages.add(package)
        inventories.append(
            {
                "importPath": package,
                "packageDirectoryRelative": package_relative.replace("\\", "/"),
                "binaryName": binary_name,
                "tests": sorted(tests),
                "sourceInventory": str(path),
                "listExitCode": payload.get("exitCode"),
            }
        )
    return sorted(inventories, key=lambda item: item["importPath"])


def load_timings(paths: Iterable[Path]) -> dict[tuple[str, str], list[float]]:
    observations: dict[tuple[str, str], list[float]] = defaultdict(list)
    for path in paths:
        try:
            handle = path.open(encoding="utf-8-sig")
        except OSError as error:
            raise ValueError(f"cannot read timing JSONL {path}: {error}") from error
        with handle:
            for line_number, line in enumerate(handle, 1):
                if not line.strip():
                    continue
                try:
                    event = json.loads(line)
                except json.JSONDecodeError as error:
                    raise ValueError(f"{path}:{line_number}: invalid JSON: {error}") from error
                action = event.get("Action")
                package = event.get("Package")
                test = event.get("Test")
                elapsed = event.get("Elapsed")
                if (
                    action in _TERMINAL_ACTIONS
                    and isinstance(package, str)
                    and isinstance(test, str)
                    and "/" not in test
                    and isinstance(elapsed, (int, float))
                    and math.isfinite(float(elapsed))
                    and float(elapsed) >= 0
                ):
                    observations[(package, test)].append(float(elapsed))
    return observations


class _TrieNode:
    __slots__ = ("children", "terminal")

    def __init__(self) -> None:
        self.children: dict[str, _TrieNode] = {}
        self.terminal = False


def _render_trie(node: _TrieNode) -> str:
    alternatives = [re.escape(char) + _render_trie(child) for char, child in sorted(node.children.items())]
    if not alternatives:
        return ""
    body = alternatives[0] if len(alternatives) == 1 else "(" + "|".join(alternatives) + ")"
    if node.terminal:
        return "(" + body + ")?"
    return body


def compressed_run_regex(names: Iterable[str]) -> str:
    ordered = sorted(set(names))
    if not ordered:
        raise ValueError("cannot build a run expression for no tests")
    root = _TrieNode()
    for name in ordered:
        node = root
        for char in name:
            node = node.children.setdefault(char, _TrieNode())
        node.terminal = True
    return "^" + _render_trie(root) + "$"


def create_plan(
    inventories: list[dict[str, Any]],
    timing_observations: dict[tuple[str, str], list[float]],
    shard_count: int,
    default_weight: float,
    timing_paths: list[Path],
) -> dict[str, Any]:
    if shard_count <= 0:
        raise ValueError("shard count must be positive")
    if not math.isfinite(default_weight) or default_weight <= 0:
        raise ValueError("default weight must be finite and positive")

    work: list[dict[str, Any]] = []
    timing_keys_used: set[tuple[str, str]] = set()
    for inventory in inventories:
        for test in inventory["tests"]:
            key = (inventory["importPath"], test)
            samples = timing_observations.get(key, [])
            if samples:
                weight = statistics.median(samples)
                source = "median-observed-elapsed"
                timing_keys_used.add(key)
            else:
                weight = default_weight
                source = "default"
            work.append(
                {
                    "importPath": inventory["importPath"],
                    "packageDirectoryRelative": inventory["packageDirectoryRelative"],
                    "binaryName": inventory["binaryName"],
                    "name": test,
                    "weightSeconds": round(weight, 6),
                    "weightSource": source,
                    "observationCount": len(samples),
                }
            )

    # Longest-processing-time first, with complete lexical tie breaking.
    work.sort(key=lambda item: (-item["weightSeconds"], item["importPath"], item["name"]))
    bins: list[list[dict[str, Any]]] = [[] for _ in range(shard_count)]
    totals = [0.0] * shard_count
    for item in work:
        destination = min(range(shard_count), key=lambda index: (totals[index], len(bins[index]), index))
        bins[destination].append(item)
        totals[destination] += item["weightSeconds"]

    shards: list[dict[str, Any]] = []
    for index, items in enumerate(bins):
        by_package: dict[str, list[dict[str, Any]]] = defaultdict(list)
        for item in items:
            by_package[item["importPath"]].append(item)
        assignments: list[dict[str, Any]] = []
        for package in sorted(by_package):
            package_items = sorted(by_package[package], key=lambda item: item["name"])
            assignments.append(
                {
                    "importPath": package,
                    "packageDirectoryRelative": package_items[0]["packageDirectoryRelative"],
                    "binaryName": package_items[0]["binaryName"],
                    "runRegex": compressed_run_regex(item["name"] for item in package_items),
                    "tests": [
                        {
                            "name": item["name"],
                            "weightSeconds": item["weightSeconds"],
                            "weightSource": item["weightSource"],
                            "observationCount": item["observationCount"],
                        }
                        for item in package_items
                    ],
                }
            )
        shards.append(
            {
                "index": index,
                "estimatedWeightSeconds": round(totals[index], 6),
                "testCount": len(items),
                "assignments": assignments,
            }
        )

    unused = sorted(
        f"{package}::{test}"
        for package, test in set(timing_observations) - timing_keys_used
    )
    return {
        "schema": SCHEMA,
        "algorithm": "deterministic-longest-processing-time-first-v1",
        "shardCount": shard_count,
        "defaultWeightSeconds": default_weight,
        "timingInputs": [str(path) for path in timing_paths],
        "packageCount": len(inventories),
        "testCount": len(work),
        "packages": inventories,
        "shards": shards,
        "diagnostics": {
            "observedTestCount": len(timing_keys_used),
            "defaultedTestCount": len(work) - len(timing_keys_used),
            "unusedTimingKeys": unused,
        },
    }


def parse_args(argv: list[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--inventory", action="append", type=Path, required=True)
    parser.add_argument("--timings", action="append", type=Path, default=[])
    parser.add_argument("--shards", type=int, required=True)
    parser.add_argument("--default-weight", type=float, default=1.0)
    parser.add_argument("--output", type=Path, required=True)
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(sys.argv[1:] if argv is None else argv)
    try:
        inventories = load_inventories(args.inventory)
        timings = load_timings(args.timings)
        plan = create_plan(inventories, timings, args.shards, args.default_weight, args.timings)
        args.output.parent.mkdir(parents=True, exist_ok=True)
        temporary = args.output.with_name(args.output.name + ".tmp")
        with temporary.open("w", encoding="utf-8", newline="\n") as handle:
            json.dump(plan, handle, indent=2, sort_keys=False)
            handle.write("\n")
        temporary.replace(args.output)
    except (ValueError, OSError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string] $PlanPath,
    [Parameter(Mandatory)][ValidateRange(0, 1023)][int] $ShardIndex,
    [Parameter(Mandatory)][string] $RepositoryPath,
    [Parameter(Mandatory)][string] $BinaryDirectory,
    [Parameter(Mandatory)][string] $OutputDirectory,
    [Parameter(Mandatory)][string] $ExpectedRepositorySha,
    [string] $GoCommand = 'go',
    [string] $Timeout = '30m',
    [string] $ResourceMonitorPath = (Join-Path $PSScriptRoot 'monitor-resources.ps1'),
    [ValidateRange(0.25, 3600.0)][double] $ResourceSampleIntervalSeconds = 2.0,
    [switch] $SkipResourceMonitor
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$nativePreferenceExists = Test-Path -LiteralPath 'variable:PSNativeCommandUseErrorActionPreference'
$originalNativePreference = $null
if ($nativePreferenceExists) {
    $originalNativePreference = $PSNativeCommandUseErrorActionPreference
    $PSNativeCommandUseErrorActionPreference = $false
}

function Write-Utf8File {
    param(
        [Parameter(Mandatory)][string] $Path,
        [Parameter(Mandatory)][AllowEmptyString()][string] $Content
    )
    [System.IO.File]::WriteAllText($Path, $Content, [System.Text.UTF8Encoding]::new($false))
}

function Write-JsonAtomically {
    param(
        [Parameter(Mandatory)][string] $Path,
        [Parameter(Mandatory)][object] $Value
    )
    $temporary = $Path + '.tmp'
    Write-Utf8File -Path $temporary -Content (ConvertTo-Json -InputObject $Value -Depth 20)
    Move-Item -LiteralPath $temporary -Destination $Path -Force
}

function ConvertTo-WindowsCommandLineArgument {
    param([Parameter(Mandatory)][AllowEmptyString()][string] $Argument)

    if ($Argument.Length -gt 0 -and $Argument -notmatch '[\s"]') {
        return $Argument
    }
    $builder = [System.Text.StringBuilder]::new()
    [void] $builder.Append('"')
    $backslashes = 0
    foreach ($character in $Argument.ToCharArray()) {
        if ($character -eq '\') {
            $backslashes++
            continue
        }
        if ($character -eq '"') {
            [void] $builder.Append(('\' * (($backslashes * 2) + 1)))
            [void] $builder.Append('"')
            $backslashes = 0
            continue
        }
        if ($backslashes -gt 0) {
            [void] $builder.Append(('\' * $backslashes))
            $backslashes = 0
        }
        [void] $builder.Append($character)
    }
    if ($backslashes -gt 0) {
        [void] $builder.Append(('\' * ($backslashes * 2)))
    }
    [void] $builder.Append('"')
    return $builder.ToString()
}

function Get-WindowsSerializedCommandLine {
    param(
        [Parameter(Mandatory)][string] $Executable,
        [Parameter(Mandatory)][string[]] $Arguments
    )
    return (@(ConvertTo-WindowsCommandLineArgument $Executable) + @(
        $Arguments | ForEach-Object { ConvertTo-WindowsCommandLineArgument ([string] $_) }
    )) -join ' '
}

function Invoke-NativeCapture {
    param(
        [Parameter(Mandatory)][string] $Command,
        [Parameter(Mandatory)][string[]] $Arguments,
        [Parameter(Mandatory)][string] $WorkingDirectory,
        [Parameter(Mandatory)][string] $StdoutPath,
        [Parameter(Mandatory)][string] $StderrPath
    )
    Write-Utf8File -Path $StdoutPath -Content ''
    Write-Utf8File -Path $StderrPath -Content ''
    $previousLocation = Get-Location
    $startedAt = [DateTimeOffset]::UtcNow
    $stopwatch = [System.Diagnostics.Stopwatch]::StartNew()
    $exitCode = 127
    $invocationError = $null
    try {
        Set-Location -LiteralPath $WorkingDirectory
        & $Command @Arguments 1> $StdoutPath 2> $StderrPath
        # For `go tool test2json <binary> ...`, test2json propagates the child
        # test binary status. Capture it before any other native command runs.
        $exitCode = $LASTEXITCODE
    }
    catch {
        $invocationError = $_.Exception.Message
        Write-Utf8File -Path $StderrPath -Content ($invocationError + [Environment]::NewLine)
    }
    finally {
        $stopwatch.Stop()
        Set-Location -LiteralPath $previousLocation.Path
    }
    return [ordered]@{
        startTimeUtc = $startedAt.ToString('o')
        endTimeUtc = [DateTimeOffset]::UtcNow.ToString('o')
        durationSeconds = [math]::Round($stopwatch.Elapsed.TotalSeconds, 6)
        exitCode = $exitCode
        stdoutPath = $StdoutPath
        stderrPath = $StderrPath
        invocationError = $invocationError
    }
}

if (-not $IsWindows) {
    throw 'run-test-shard.ps1 must be executed by PowerShell 7 on Windows.'
}
if ($Timeout -notmatch '^\d+(ns|us|µs|ms|s|m|h)$') {
    throw "invalid Go test timeout: $Timeout"
}

$resolvedPlan = (Resolve-Path -LiteralPath $PlanPath).ProviderPath
$resolvedRepository = (Resolve-Path -LiteralPath $RepositoryPath).ProviderPath
$resolvedBinaryDirectory = (Resolve-Path -LiteralPath $BinaryDirectory).ProviderPath
$resolvedOutput = [System.IO.Path]::GetFullPath($OutputDirectory)
New-Item -ItemType Directory -Path $resolvedOutput -Force | Out-Null
$metadataPath = Join-Path $resolvedOutput 'shard-metadata.json'
$combinedEventsPath = Join-Path $resolvedOutput 'shard-events.jsonl'
$monitorStopFile = Join-Path $resolvedOutput '.resource-monitor.stop'
$resourcePath = Join-Path $resolvedOutput 'resource-samples.jsonl'
Write-Utf8File -Path $combinedEventsPath -Content ''

$plan = Get-Content -LiteralPath $resolvedPlan -Raw | ConvertFrom-Json
if ($plan.schema -ne 'ci-bench.test-shard-plan.v1') {
    throw "unexpected plan schema: $($plan.schema)"
}
if ($ShardIndex -ge [int] $plan.shardCount) {
    throw "shard index $ShardIndex is outside plan shard count $($plan.shardCount)"
}
$shard = @($plan.shards | Where-Object { [int] $_.index -eq $ShardIndex })
if ($shard.Count -ne 1) {
    throw "plan does not contain exactly one shard with index $ShardIndex"
}
$shard = $shard[0]

$go = Get-Command -Name $GoCommand -CommandType Application -ErrorAction Stop
$resolvedGo = $go.Source
$metadata = [ordered]@{
    schema = 'ci-bench.test-shard-run.v1'
    state = 'initializing'
    shardIndex = $ShardIndex
    shardCount = [int] $plan.shardCount
    planPath = $resolvedPlan
    repositoryPath = $resolvedRepository
    binaryDirectory = $resolvedBinaryDirectory
    expectedRepositorySha = $ExpectedRepositorySha
    repositorySha = $null
    goos = 'windows'
    goarch = 'amd64'
    cgoEnabled = '1'
    timeout = $Timeout
    startTimeUtc = [DateTimeOffset]::UtcNow.ToString('o')
    endTimeUtc = $null
    durationSeconds = $null
    exitCode = $null
    cleanTestCacheExitCode = $null
    invocations = [System.Collections.Generic.List[object]]::new()
    eventsPath = $combinedEventsPath
    resourceSamplesPath = if ($SkipResourceMonitor) { $null } else { $resourcePath }
    commandLineLimit = 32767
    batching = [ordered]@{
        enabled = $false
        processCountPerPackageInThisShard = 1
        note = 'No command-line batching: compressed regexes must fit or the run fails closed.'
    }
    processSemantics = 'Each package TestMain/init runs once in this shard; a package assigned to multiple shards runs TestMain/init once per shard.'
    errors = [System.Collections.Generic.List[string]]::new()
}
Write-JsonAtomically -Path $metadataPath -Value $metadata

$originalGoEnvironment = [ordered]@{
    GOOS = [Environment]::GetEnvironmentVariable('GOOS', 'Process')
    GOARCH = [Environment]::GetEnvironmentVariable('GOARCH', 'Process')
    CGO_ENABLED = [Environment]::GetEnvironmentVariable('CGO_ENABLED', 'Process')
}
$monitorJob = $null
$startedAt = [DateTimeOffset]::Parse($metadata.startTimeUtc)
$finalExitCode = 0
try {
    $env:GOOS = 'windows'
    $env:GOARCH = 'amd64'
    $env:CGO_ENABLED = '1'

    $sha = @(& git '-C' $resolvedRepository 'rev-parse' 'HEAD' 2>&1 | ForEach-Object { [string] $_ })
    $shaExitCode = $LASTEXITCODE
    if ($shaExitCode -ne 0) {
        throw "git rev-parse failed with exit code $shaExitCode"
    }
    $metadata.repositorySha = ($sha -join '').Trim()
    if ($metadata.repositorySha -ne $ExpectedRepositorySha) {
        throw "repository SHA '$($metadata.repositorySha)' does not match '$ExpectedRepositorySha'"
    }

    & $resolvedGo 'clean' '-testcache' 1> (Join-Path $resolvedOutput 'clean-testcache.stdout.log') 2> (Join-Path $resolvedOutput 'clean-testcache.stderr.log')
    $metadata.cleanTestCacheExitCode = $LASTEXITCODE
    if ($metadata.cleanTestCacheExitCode -ne 0) {
        throw "go clean -testcache failed with exit code $($metadata.cleanTestCacheExitCode)"
    }

    if (-not $SkipResourceMonitor) {
        $resolvedMonitor = (Resolve-Path -LiteralPath $ResourceMonitorPath).ProviderPath
        if (Test-Path -LiteralPath $monitorStopFile) {
            Remove-Item -LiteralPath $monitorStopFile -Force
        }
        $monitorJob = Start-Job -FilePath $resolvedMonitor -ArgumentList @(
            $resourcePath, $monitorStopFile, $ResourceSampleIntervalSeconds, 0, 0
        )
    }
    $metadata.state = 'running'
    Write-JsonAtomically -Path $metadataPath -Value $metadata

    $assignmentNumber = 0
    foreach ($assignment in @($shard.assignments)) {
        $package = [string] $assignment.importPath
        $relativeDirectory = ([string] $assignment.packageDirectoryRelative).Replace('/', [System.IO.Path]::DirectorySeparatorChar)
        if ([System.IO.Path]::IsPathRooted($relativeDirectory) -or
            $relativeDirectory -eq '..' -or
            $relativeDirectory.StartsWith('..' + [System.IO.Path]::DirectorySeparatorChar)) {
            throw "unsafe package directory in plan: $relativeDirectory"
        }
        $packageDirectory = [System.IO.Path]::GetFullPath((Join-Path $resolvedRepository $relativeDirectory))
        $binaryName = [System.IO.Path]::GetFileName([string] $assignment.binaryName)
        if ($binaryName -ne [string] $assignment.binaryName) {
            throw "unsafe binary name in plan: $($assignment.binaryName)"
        }
        $binary = (Resolve-Path -LiteralPath (Join-Path $resolvedBinaryDirectory $binaryName)).ProviderPath
        $runExpression = [string] $assignment.runRegex
        if ([string]::IsNullOrWhiteSpace($runExpression)) {
            throw "empty run regex for package $package"
        }
        $arguments = @(
            'tool', 'test2json', '-t', '-p', $package, $binary,
            "-test.timeout=$Timeout", "-test.run=$runExpression", '-test.v=test2json'
        )
        $serialized = Get-WindowsSerializedCommandLine -Executable $resolvedGo -Arguments $arguments
        # CreateProcessW's 32,767-character limit includes the terminating NUL.
        $serializedLengthWithNull = $serialized.Length + 1
        if ($serializedLengthWithNull -gt 32767) {
            throw "serialized Windows argv is $serializedLengthWithNull characters for $package; refusing implicit batching because it would repeat TestMain/init"
        }
        $stem = ('{0:d2}-{1}' -f $assignmentNumber, ($package -replace '[^A-Za-z0-9_.-]', '_'))
        $stdoutPath = Join-Path $resolvedOutput ($stem + '.jsonl')
        $stderrPath = Join-Path $resolvedOutput ($stem + '.stderr.log')
        $result = Invoke-NativeCapture -Command $resolvedGo -Arguments $arguments -WorkingDirectory $packageDirectory -StdoutPath $stdoutPath -StderrPath $stderrPath
        $result.package = $package
        $result.packageDirectory = $packageDirectory
        $result.binaryPath = $binary
        $result.runRegex = $runExpression
        $result.testCount = @($assignment.tests).Count
        $result.commandLine = $serialized
        $result.serializedLengthWithNull = $serializedLengthWithNull
        $metadata.invocations.Add($result)
        if (Test-Path -LiteralPath $stdoutPath) {
            $content = Get-Content -LiteralPath $stdoutPath -Raw
            if (-not [string]::IsNullOrEmpty($content)) {
                [System.IO.File]::AppendAllText($combinedEventsPath, $content, [System.Text.UTF8Encoding]::new($false))
                if (-not $content.EndsWith("`n")) {
                    [System.IO.File]::AppendAllText($combinedEventsPath, "`n", [System.Text.UTF8Encoding]::new($false))
                }
            }
        }
        if ($result.exitCode -ne 0 -and $finalExitCode -eq 0) {
            $finalExitCode = [int] $result.exitCode
        }
        Write-JsonAtomically -Path $metadataPath -Value $metadata
        $assignmentNumber++
    }
}
catch {
    $metadata.errors.Add($_.Exception.Message)
    if ($finalExitCode -eq 0) {
        $finalExitCode = 2
    }
}
finally {
    if ($null -ne $monitorJob) {
        Write-Utf8File -Path $monitorStopFile -Content ([DateTimeOffset]::UtcNow.ToString('o'))
        Wait-Job -Job $monitorJob -Timeout 30 | Out-Null
        if ($monitorJob.State -eq 'Running') {
            Stop-Job -Job $monitorJob
            $metadata.errors.Add('resource monitor did not stop within 30 seconds')
            if ($finalExitCode -eq 0) { $finalExitCode = 2 }
        }
        Receive-Job -Job $monitorJob -ErrorAction Continue | Out-Null
        Remove-Job -Job $monitorJob -Force
    }
    [Environment]::SetEnvironmentVariable('GOOS', $originalGoEnvironment.GOOS, 'Process')
    [Environment]::SetEnvironmentVariable('GOARCH', $originalGoEnvironment.GOARCH, 'Process')
    [Environment]::SetEnvironmentVariable('CGO_ENABLED', $originalGoEnvironment.CGO_ENABLED, 'Process')
    if ($nativePreferenceExists) {
        $PSNativeCommandUseErrorActionPreference = $originalNativePreference
    }
    $endedAt = [DateTimeOffset]::UtcNow
    $metadata.endTimeUtc = $endedAt.ToString('o')
    $metadata.durationSeconds = [math]::Round(($endedAt - $startedAt).TotalSeconds, 6)
    $metadata.exitCode = $finalExitCode
    $metadata.state = if ($finalExitCode -eq 0) { 'completed' } else { 'failed' }
    Write-JsonAtomically -Path $metadataPath -Value $metadata
}

exit $finalExitCode
#!/usr/bin/env python3
"""Fail-closed coverage-equivalence checks for compile-once test shards."""

from __future__ import annotations

import argparse
import collections
import json
import re
import sys
from pathlib import Path
from typing import Any, Iterable, Iterator


PLAN_SCHEMA = "ci-bench.test-shard-plan.v1"
INVENTORY_SCHEMA = "ci-bench.compiled-test-inventory.v1"
PACKAGE_SCHEMA = "ci-bench.windows-package-inventory.v1"
REPORT_SCHEMA = "ci-bench.shard-equivalence.v1"
_ACTIONS = frozenset({"run", "pass", "fail", "skip"})
_TERMINAL_ACTIONS = frozenset({"pass", "fail", "skip"})


def read_json(path: Path) -> Any:
    try:
        with path.open(encoding="utf-8-sig") as handle:
            return json.load(handle)
    except (OSError, json.JSONDecodeError) as error:
        raise ValueError(f"cannot read JSON {path}: {error}") from error


def read_events(paths: Iterable[Path]) -> list[dict[str, Any]]:
    events: list[dict[str, Any]] = []
    for path in paths:
        try:
            handle = path.open(encoding="utf-8-sig")
        except OSError as error:
            raise ValueError(f"cannot read JSONL {path}: {error}") from error
        with handle:
            for line_number, line in enumerate(handle, 1):
                if not line.strip():
                    continue
                try:
                    value = json.loads(line)
                except json.JSONDecodeError as error:
                    raise ValueError(f"{path}:{line_number}: invalid JSON: {error}") from error
                if not isinstance(value, dict):
                    raise ValueError(f"{path}:{line_number}: event is not an object")
                events.append(value)
    return events


def dynamic_counter(events: Iterable[dict[str, Any]]) -> collections.Counter[tuple[str, str, str]]:
    result: collections.Counter[tuple[str, str, str]] = collections.Counter()
    for event in events:
        action = event.get("Action")
        package = event.get("Package")
        test = event.get("Test")
        if action in _ACTIONS and isinstance(package, str) and isinstance(test, str):
            result[(action, package, test)] += 1
    return result


def package_terminal_counter(events: Iterable[dict[str, Any]]) -> collections.Counter[tuple[str, str]]:
    result: collections.Counter[tuple[str, str]] = collections.Counter()
    for event in events:
        action = event.get("Action")
        package = event.get("Package")
        if action in _TERMINAL_ACTIONS and isinstance(package, str) and "Test" not in event:
            result[(action, package)] += 1
    return result


def package_terminal_actions(
    counter: collections.Counter[tuple[str, str]],
) -> dict[str, set[str]]:
    result: collections.defaultdict[str, set[str]] = collections.defaultdict(set)
    for (action, package), count in counter.items():
        if count:
            result[package].add(action)
    return dict(result)


def format_counter(counter: collections.Counter[Any], limit: int = 100) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for key, count in sorted(counter.items(), key=lambda item: item[0])[:limit]:
        if len(key) == 3:
            action, package, test = key
            rows.append({"action": action, "package": package, "test": test, "count": count})
        else:
            action, package = key
            rows.append({"action": action, "package": package, "count": count})
    return rows


def walk_exit_codes(value: Any, location: str = "$") -> Iterator[tuple[str, Any]]:
    if isinstance(value, dict):
        for key, child in value.items():
            child_location = f"{location}.{key}"
            if key.lower().endswith("exitcode"):
                yield child_location, child
            yield from walk_exit_codes(child, child_location)
    elif isinstance(value, list):
        for index, child in enumerate(value):
            yield from walk_exit_codes(child, f"{location}[{index}]")


def load_expected_inventories(paths: list[Path]) -> dict[str, dict[str, Any]]:
    result: dict[str, dict[str, Any]] = {}
    for path in paths:
        payload = read_json(path)
        if payload.get("schema") != INVENTORY_SCHEMA:
            raise ValueError(f"{path}: unexpected inventory schema {payload.get('schema')!r}")
        package = payload.get("importPath")
        tests = payload.get("tests")
        if not isinstance(package, str) or not package or not isinstance(tests, list):
            raise ValueError(f"{path}: malformed compiled-test inventory")
        if package in result:
            raise ValueError(f"duplicate inventory package: {package}")
        if any(not isinstance(test, str) for test in tests) or len(tests) != len(set(tests)):
            raise ValueError(f"{path}: tests must be unique strings")
        result[package] = {"tests": set(tests), "path": str(path), "exitCode": payload.get("exitCode")}
    return result


def verify_plan(
    plan: dict[str, Any], inventories: dict[str, dict[str, Any]], failures: list[str]
) -> dict[str, Any]:
    if plan.get("schema") != PLAN_SCHEMA:
        raise ValueError(f"unexpected shard plan schema {plan.get('schema')!r}")
    shards = plan.get("shards")
    if not isinstance(shards, list) or len(shards) != plan.get("shardCount"):
        failures.append("plan shard count does not match its shard array")
        shards = []

    occurrences: collections.defaultdict[tuple[str, str], list[int]] = collections.defaultdict(list)
    regex_mismatches: list[dict[str, Any]] = []
    for position, shard in enumerate(shards):
        if shard.get("index") != position:
            failures.append(f"shard at position {position} has index {shard.get('index')!r}")
        assignments = shard.get("assignments")
        if not isinstance(assignments, list):
            failures.append(f"shard {position} assignments are not a list")
            continue
        seen_package: set[str] = set()
        for assignment in assignments:
            package = assignment.get("importPath")
            tests = assignment.get("tests")
            expression = assignment.get("runRegex")
            if not isinstance(package, str) or package in seen_package:
                failures.append(f"shard {position} has a missing or duplicate package assignment")
                continue
            seen_package.add(package)
            if not isinstance(tests, list) or not isinstance(expression, str):
                failures.append(f"shard {position} package {package} has malformed tests/regex")
                continue
            names = [test.get("name") if isinstance(test, dict) else None for test in tests]
            if any(not isinstance(name, str) for name in names) or len(names) != len(set(names)):
                failures.append(f"shard {position} package {package} has malformed or duplicate tests")
                continue
            try:
                compiled = re.compile(expression)
            except re.error as error:
                failures.append(f"shard {position} package {package} regex is invalid: {error}")
                continue
            package_inventory = inventories.get(package, {}).get("tests", set())
            matched = {test for test in package_inventory if compiled.fullmatch(test)}
            planned = set(names)
            if matched != planned:
                regex_mismatches.append(
                    {
                        "shard": position,
                        "package": package,
                        "missing": sorted(planned - matched),
                        "unexpected": sorted(matched - planned),
                    }
                )
            for name in names:
                occurrences[(package, name)].append(position)

    expected = {
        (package, test)
        for package, inventory in inventories.items()
        for test in inventory["tests"]
    }
    assigned = set(occurrences)
    missing = sorted(f"{package}::{test}" for package, test in expected - assigned)
    unexpected = sorted(f"{package}::{test}" for package, test in assigned - expected)
    duplicated = sorted(
        (
            {"test": f"{package}::{test}", "shards": shards_for_test}
            for (package, test), shards_for_test in occurrences.items()
            if len(shards_for_test) != 1
        ),
        key=lambda item: item["test"],
    )
    if missing:
        failures.append(f"{len(missing)} compiled tests are missing from the plan")
    if unexpected:
        failures.append(f"{len(unexpected)} plan tests are absent from compiled inventories")
    if duplicated:
        failures.append(f"{len(duplicated)} tests are assigned more than once")
    if regex_mismatches:
        failures.append(f"{len(regex_mismatches)} shard regexes select the wrong inventory")
    return {
        "expectedTestCount": len(expected),
        "assignedTestCount": len(assigned),
        "missing": missing,
        "unexpected": unexpected,
        "duplicates": duplicated,
        "regexMismatches": regex_mismatches,
    }


def load_package_inventory(path: Path) -> set[str]:
    payload = read_json(path)
    if payload.get("schema") != PACKAGE_SCHEMA or not isinstance(payload.get("packages"), list):
        raise ValueError(f"{path}: malformed Windows package inventory")
    packages: set[str] = set()
    for item in payload["packages"]:
        package = item.get("importPath") if isinstance(item, dict) else item
        if not isinstance(package, str) or not package or package in packages:
            raise ValueError(f"{path}: package entries must be unique import paths")
        packages.add(package)
    return packages


def write_report(path: Path, report: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    with temporary.open("w", encoding="utf-8", newline="\n") as handle:
        json.dump(report, handle, indent=2)
        handle.write("\n")
    temporary.replace(path)


def parse_args(argv: list[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--baseline-events", type=Path, required=True)
    parser.add_argument("--candidate-events", type=Path, action="append", required=True)
    parser.add_argument("--plan", type=Path, required=True)
    parser.add_argument("--inventory", type=Path, action="append", required=True)
    parser.add_argument("--package-inventory", type=Path, required=True)
    parser.add_argument("--metadata", type=Path, action="append", required=True)
    parser.add_argument("--output", type=Path, required=True)
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(sys.argv[1:] if argv is None else argv)
    failures: list[str] = []
    report: dict[str, Any] = {
        "schema": REPORT_SCHEMA,
        "equivalent": False,
        "failures": failures,
        "inputs": {
            "baselineEvents": str(args.baseline_events),
            "candidateEvents": [str(path) for path in args.candidate_events],
            "plan": str(args.plan),
            "inventories": [str(path) for path in args.inventory],
            "packageInventory": str(args.package_inventory),
            "metadata": [str(path) for path in args.metadata],
        },
    }
    try:
        inventories = load_expected_inventories(args.inventory)
        for package, inventory in inventories.items():
            if inventory["exitCode"] != 0:
                failures.append(f"compiled inventory listing failed for {package}: {inventory['exitCode']!r}")
        plan = read_json(args.plan)
        report["topLevelInventory"] = verify_plan(plan, inventories, failures)

        baseline_events = read_events([args.baseline_events])
        candidate_events = read_events(args.candidate_events)
        baseline_dynamic = dynamic_counter(baseline_events)
        candidate_dynamic = dynamic_counter(candidate_events)
        missing_dynamic = baseline_dynamic - candidate_dynamic
        extra_dynamic = candidate_dynamic - baseline_dynamic
        if missing_dynamic or extra_dynamic:
            failures.append("fully qualified dynamic run/pass/fail/skip event multisets differ")
        report["dynamicEvents"] = {
            "baselineCount": sum(baseline_dynamic.values()),
            "candidateCount": sum(candidate_dynamic.values()),
            "missing": format_counter(missing_dynamic),
            "extra": format_counter(extra_dynamic),
            "differencesTruncated": len(missing_dynamic) > 100 or len(extra_dynamic) > 100,
        }

        expected_packages = load_package_inventory(args.package_inventory)
        baseline_packages = {package for _, package in package_terminal_counter(baseline_events)}
        candidate_packages = {package for _, package in package_terminal_counter(candidate_events)}
        for label, actual in (("baseline", baseline_packages), ("candidate", candidate_packages)):
            if actual != expected_packages:
                failures.append(f"{label} package result inventory differs from target-Windows go list inventory")
        baseline_package_results = package_terminal_counter(baseline_events)
        candidate_package_results = package_terminal_counter(candidate_events)
        baseline_outcomes = package_terminal_actions(baseline_package_results)
        candidate_outcomes = package_terminal_actions(candidate_package_results)
        outcome_mismatches = [
            {
                "package": package,
                "baseline": sorted(baseline_outcomes.get(package, set())),
                "candidate": sorted(candidate_outcomes.get(package, set())),
            }
            for package in sorted(expected_packages)
            if baseline_outcomes.get(package, set()) != candidate_outcomes.get(package, set())
        ]
        if outcome_mismatches:
            failures.append("package terminal outcome sets differ between baseline and candidate")
        # `go test -json` reports packages without test files as package-level
        # skips with a successful process exit. Preserve and compare those
        # skips; only a package-level fail is intrinsically bad.
        baseline_bad_results = collections.Counter(
            {key: count for key, count in baseline_package_results.items() if key[0] == "fail"}
        )
        candidate_bad_results = collections.Counter(
            {key: count for key, count in candidate_package_results.items() if key[0] == "fail"}
        )
        if baseline_bad_results:
            failures.append("baseline contains non-passing package terminal results")
        if candidate_bad_results:
            failures.append("candidate contains non-passing package terminal results")
        report["packages"] = {
            "expected": sorted(expected_packages),
            "baselineMissing": sorted(expected_packages - baseline_packages),
            "baselineUnexpected": sorted(baseline_packages - expected_packages),
            "candidateMissing": sorted(expected_packages - candidate_packages),
            "candidateUnexpected": sorted(candidate_packages - expected_packages),
            # Heavy packages intentionally emit one package-level result per
            # process/shard, so package terminal-result *multiplicity* cannot
            # equal the monolithic baseline. Top-level test-event multiplicity
            # above remains exact; here we prove set coverage and successful
            # completion while exposing the deliberate package repetition.
            "baselineTerminalResults": format_counter(baseline_package_results),
            "candidateTerminalResults": format_counter(candidate_package_results),
            "outcomeMismatches": outcome_mismatches,
            "baselineFailedResults": format_counter(baseline_bad_results),
            "candidateFailedResults": format_counter(candidate_bad_results),
        }

        exit_checks: list[dict[str, Any]] = []
        for path in args.metadata:
            payload = read_json(path)
            codes = list(walk_exit_codes(payload))
            if not codes:
                failures.append(f"metadata has no exit-code fields: {path}")
            for location, value in codes:
                passed = isinstance(value, int) and not isinstance(value, bool) and value == 0
                exit_checks.append(
                    {"path": str(path), "location": location, "value": value, "passed": passed}
                )
                if not passed:
                    failures.append(f"nonzero, null, or non-integer exit code at {path}:{location}: {value!r}")
        report["exitCodes"] = exit_checks
        report["equivalent"] = not failures
    except (ValueError, OSError) as error:
        failures.append(str(error))
    try:
        write_report(args.output, report)
    except OSError as error:
        print(f"error: cannot write report {args.output}: {error}", file=sys.stderr)
        return 2
    if failures:
        for failure in failures:
            print(f"FAIL: {failure}", file=sys.stderr)
        return 1
    print("coverage-equivalence verification passed")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

