function Get-StorageToken {
    $uri = 'http://169.254.169.254/metadata/identity/oauth2/token?api-version=2018-02-01&resource=https%3A%2F%2Fstorage.azure.com%2F'
    return (Invoke-RestMethod -Headers @{ Metadata = 'true' } -Uri $uri -Method Get).access_token
}

function Get-Blob {
    param([string] $Uri, [string] $Path)
    $headers = @{ Authorization = 'Bearer ' + (Get-StorageToken); 'x-ms-version' = '2023-11-03' }
    Invoke-WebRequest -UseBasicParsing -Headers $headers -Uri $Uri -OutFile $Path
}

function Put-Blob {
    param([string] $Uri, [string] $Path)
    $headers = @{
        Authorization = 'Bearer ' + (Get-StorageToken)
        'x-ms-version' = '2023-11-03'
        'x-ms-blob-type' = 'BlockBlob'
    }
    Invoke-WebRequest -UseBasicParsing -Headers $headers -Uri $Uri -Method Put -InFile $Path | Out-Null
}

function Restore-SeedCache {
    param([string] $Destination)
    if (Test-Path -LiteralPath $Destination) { Remove-Item -LiteralPath $Destination -Recurse -Force }
    Copy-Item -LiteralPath $seed -Destination $Destination -Recurse -Force
}

function Write-Json {
    param([string] $Path, [object] $Value)
    $Value | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $Path -Encoding utf8NoBOM
}

$controlPath = Join-Path $root 'treatment-control.json'
Get-Blob -Uri "https://$storageAccount.blob.core.windows.net/staging/treatment-control.json" -Path $controlPath
$control = Get-Content -LiteralPath $controlPath -Raw | ConvertFrom-Json
$label = [string] $control.label
$shardCount = [int] $control.shards
if ($label -notmatch '^[a-z0-9-]{1,40}$') { throw "unsafe treatment label: $label" }
if ($shardCount -notin @(4, 6, 8)) { throw "unsupported shard count: $shardCount" }
foreach ($required in $seed, $packageInventoryPath, $otherPackagesPath, $baselineEventsPath) {
    if (-not (Test-Path -LiteralPath $required)) { throw "required baseline artifact is missing: $required" }
}

$treatment = Join-Path $resultRoot $label
$work = Join-Path $root "work\$label"
foreach ($path in $treatment, $work) {
    if (Test-Path -LiteralPath $path) { Remove-Item -LiteralPath $path -Recurse -Force }
    New-Item -ItemType Directory -Path $path -Force | Out-Null
}
$binaryDirectory = Join-Path $work 'compiled-binaries'
New-Item -ItemType Directory -Path $binaryDirectory -Force | Out-Null
$cacheRoot = Join-Path $root "cache\$label"
if (Test-Path -LiteralPath $cacheRoot) { Remove-Item -LiteralPath $cacheRoot -Recurse -Force }
New-Item -ItemType Directory -Path $cacheRoot -Force | Out-Null
$compileCache = Join-Path $cacheRoot 'compile'
$otherCache = Join-Path $cacheRoot 'other'
$vetCache = Join-Path $cacheRoot 'vet'
Restore-SeedCache $compileCache
Restore-SeedCache $otherCache
Restore-SeedCache $vetCache

$monitorStop = Join-Path $treatment '.resource-monitor.stop'
$monitorJob = Start-Job -FilePath (Join-Path $harness 'monitor-resources.ps1') -ArgumentList @(
    (Join-Path $treatment 'resource-samples.jsonl'), $monitorStop, 2, 0, 0
)
$treatmentStart = [DateTimeOffset]::UtcNow
$treatmentWatch = [Diagnostics.Stopwatch]::StartNew()
$driverErrors = [Collections.Generic.List[string]]::new()
$finalExitCode = 0
$compileExitCode = 0
$uploadExitCode = 2
$verifierExitCode = 2
$otherProcess = $null
$vetProcess = $null
$downloadProcesses = @()
$shardProcesses = @()

try {
    $otherOut = Join-Path $treatment 'other-packages'
    $vetOut = Join-Path $treatment 'strengthened-vet'
    $otherArgs = @(
        '-NoProfile', '-File', (Join-Path $experiment 'azure-other-packages.ps1'),
        '-RepositoryPath', $repo, '-PackagesPath', $otherPackagesPath,
        '-CachePath', $otherCache, '-OutputDirectory', $otherOut
    )
    $vetArgs = @(
        '-NoProfile', '-File', (Join-Path $experiment 'azure-vet.ps1'),
        '-RepositoryPath', $repo, '-CachePath', $vetCache, '-OutputDirectory', $vetOut
    )
    $otherProcess = Start-Process -FilePath 'pwsh' -ArgumentList $otherArgs -PassThru
    $vetProcess = Start-Process -FilePath 'pwsh' -ArgumentList $vetArgs -PassThru

    $env:GOCACHE = $compileCache
    $compileStarted = [DateTimeOffset]::UtcNow
    $compileWatch = [Diagnostics.Stopwatch]::StartNew()
    $compileMetrics = [Collections.Generic.List[object]]::new()
    $heavyPackages = @(
        @{ argument = './internal/sem'; binary = 'sem.test.exe' },
        @{ argument = './internal/cli'; binary = 'cli.test.exe' },
        @{ argument = './internal/gitutil'; binary = 'gitutil.test.exe' }
    )
    foreach ($package in $heavyPackages) {
        $binary = Join-Path $binaryDirectory $package.binary
        $stdout = Join-Path $treatment ($package.binary + '.compile.stdout.log')
        $stderr = Join-Path $treatment ($package.binary + '.compile.stderr.log')
        $watch = [Diagnostics.Stopwatch]::StartNew()
        Push-Location $repo
        try {
            # Fidelity candidate: retain go test's default vet. The separate
            # standalone vet job is therefore strengthened coverage.
            & go test -c $package.argument -o $binary 1> $stdout 2> $stderr
            $code = $LASTEXITCODE
        }
        finally { Pop-Location; $watch.Stop() }
        $compileMetrics.Add([ordered]@{
            package = $package.argument
            binary = $package.binary
            vetMode = 'default go test vet'
            durationSeconds = [math]::Round($watch.Elapsed.TotalSeconds, 6)
            bytes = if (Test-Path -LiteralPath $binary) { (Get-Item -LiteralPath $binary).Length } else { 0 }
            exitCode = $code
        })
        if ($code -ne 0) { $compileExitCode = $code; throw "compile failed for $($package.argument): $code" }
        $inventory = Join-Path $treatment ($package.binary + '.inventory.json')
        & pwsh -NoProfile -File (Join-Path $harness 'list-tests.ps1') `
            -RepositoryPath $repo -BinaryPath $binary `
            -PackageArgument $package.argument -OutputPath $inventory
        $inventoryCode = $LASTEXITCODE
        if ($inventoryCode -ne 0) { $compileExitCode = $inventoryCode; throw "inventory failed for $($package.argument): $inventoryCode" }
    }
    $compileWatch.Stop()
    $compileDuration = $compileWatch.Elapsed.TotalSeconds

    $inventoryArgs = @()
    Get-ChildItem -LiteralPath $treatment -Filter '*.inventory.json' | Sort-Object Name | ForEach-Object {
        $inventoryArgs += @('--inventory', $_.FullName)
    }
    $planPath = Join-Path $treatment 'shard-plan.json'
    & python (Join-Path $harness 'partition-tests.py') @inventoryArgs `
        --timings $baselineEventsPath --shards $shardCount --output $planPath
    $partitionExitCode = $LASTEXITCODE
    if ($partitionExitCode -ne 0) { $compileExitCode = $partitionExitCode; throw "partition failed: $partitionExitCode" }

    $binaryZip = Join-Path $work 'compiled-binaries.zip'
    Compress-Archive -Path (Join-Path $binaryDirectory '*') -DestinationPath $binaryZip -CompressionLevel Optimal
    $blobUri = "https://$storageAccount.blob.core.windows.net/results/artifacts/$label/compiled-binaries.zip"
    $uploadWatch = [Diagnostics.Stopwatch]::StartNew()
    Put-Blob -Uri $blobUri -Path $binaryZip
    $uploadWatch.Stop()
    $uploadExitCode = 0
    $uploadDuration = $uploadWatch.Elapsed.TotalSeconds
    Write-Json -Path (Join-Path $treatment 'compile-metadata.json') -Value ([ordered]@{
        schema = 'ci-bench.a2-compile-once.v1'
        startTimeUtc = $compileStarted.ToString('o')
        endTimeUtc = [DateTimeOffset]::UtcNow.ToString('o')
        durationSeconds = [math]::Round($compileDuration, 6)
        vetMode = 'default go test vet'
        exitCode = $compileExitCode
        partitionExitCode = $partitionExitCode
        artifactUploadExitCode = $uploadExitCode
        artifactUploadDurationSeconds = [math]::Round($uploadDuration, 6)
        artifactBytes = (Get-Item -LiteralPath $binaryZip).Length
        packages = $compileMetrics
    })

    for ($index = 0; $index -lt $shardCount; $index++) {
        $downloadRoot = Join-Path $work "download-$index"
        $downloadZip = Join-Path $downloadRoot 'compiled-binaries.zip'
        $extract = Join-Path $downloadRoot 'binaries'
        New-Item -ItemType Directory -Path $downloadRoot -Force | Out-Null
        $downloadMetadata = Join-Path $treatment "download-$index-metadata.json"
        $args = @(
            '-NoProfile', '-File', (Join-Path $experiment 'azure-download-artifact.ps1'),
            '-BlobUri', $blobUri, '-ZipPath', $downloadZip,
            '-ExtractDirectory', $extract, '-MetadataPath', $downloadMetadata
        )
        $downloadProcesses += Start-Process -FilePath 'pwsh' -ArgumentList $args -PassThru
    }
    $downloadProcesses | Wait-Process
    foreach ($process in $downloadProcesses) {
        if ($process.ExitCode -ne 0) { throw "artifact download process failed: $($process.ExitCode)" }
    }

    for ($index = 0; $index -lt $shardCount; $index++) {
        $shardCache = Join-Path $cacheRoot "shard-$index"
        Restore-SeedCache $shardCache
        $args = @(
            '-NoProfile', '-File', (Join-Path $experiment 'azure-shard-wrapper.ps1'),
            '-HarnessPath', $harness, '-PlanPath', $planPath, '-ShardIndex', $index,
            '-RepositoryPath', $repo,
            '-BinaryDirectory', (Join-Path $work "download-$index\binaries"),
            '-CachePath', $shardCache,
            '-OutputDirectory', (Join-Path $treatment "shard-$index"),
            '-ExpectedRepositorySha', $productSha
        )
        $shardProcesses += Start-Process -FilePath 'pwsh' -ArgumentList $args -PassThru
    }
    $shardProcesses | Wait-Process
    foreach ($process in $shardProcesses) {
        if ($process.ExitCode -ne 0) { throw "shard process failed: $($process.ExitCode)" }
    }
}
catch {
    $driverErrors.Add($_.Exception.Message)
    if ($finalExitCode -eq 0) { $finalExitCode = 2 }
}
finally {
    foreach ($process in @($otherProcess, $vetProcess)) {
        if ($null -ne $process -and -not $process.HasExited) { $process | Wait-Process }
        if ($null -ne $process -and $process.ExitCode -ne 0) {
            $driverErrors.Add("concurrent process $($process.Id) exited $($process.ExitCode)")
            if ($finalExitCode -eq 0) { $finalExitCode = $process.ExitCode }
        }
    }
    Set-Content -LiteralPath $monitorStop -Value ([DateTimeOffset]::UtcNow.ToString('o')) -Encoding ascii
    Wait-Job -Job $monitorJob -Timeout 30 | Out-Null
    if ($monitorJob.State -eq 'Running') { Stop-Job -Job $monitorJob }
    Receive-Job -Job $monitorJob -ErrorAction Continue | Out-Null
    Remove-Job -Job $monitorJob -Force
}

$compileMetadataPath = Join-Path $treatment 'compile-metadata.json'
$otherMetadataPath = Join-Path $treatment 'other-packages\other-metadata.json'
$vetMetadataPath = Join-Path $treatment 'strengthened-vet\vet-metadata.json'
if ($finalExitCode -eq 0) {
    $verifyArgs = @(
        '--baseline-events', $baselineEventsPath,
        '--plan', (Join-Path $treatment 'shard-plan.json'),
        '--package-inventory', $packageInventoryPath,
        '--output', (Join-Path $treatment 'equivalence.json'),
        '--metadata', $compileMetadataPath,
        '--metadata', $otherMetadataPath,
        '--metadata', $vetMetadataPath,
        '--candidate-events', (Join-Path $treatment 'other-packages\other-events.jsonl')
    )
    Get-ChildItem -LiteralPath $treatment -Filter '*.inventory.json' | Sort-Object Name | ForEach-Object {
        $verifyArgs += @('--inventory', $_.FullName)
    }
    for ($index = 0; $index -lt $shardCount; $index++) {
        $verifyArgs += @('--candidate-events', (Join-Path $treatment "shard-$index\shard-events.jsonl"))
        $verifyArgs += @('--metadata', (Join-Path $treatment "shard-$index\shard-metadata.json"))
        $verifyArgs += @('--metadata', (Join-Path $treatment "download-$index-metadata.json"))
    }
    & python (Join-Path $harness 'verify-shard-inventory.py') @verifyArgs
    $verifierExitCode = $LASTEXITCODE
    if ($verifierExitCode -ne 0) { $finalExitCode = $verifierExitCode }
}

$treatmentWatch.Stop()
$compileMetadata = if (Test-Path -LiteralPath $compileMetadataPath) { Get-Content -LiteralPath $compileMetadataPath -Raw | ConvertFrom-Json } else { $null }
$otherMetadata = if (Test-Path -LiteralPath $otherMetadataPath) { Get-Content -LiteralPath $otherMetadataPath -Raw | ConvertFrom-Json } else { $null }
$vetMetadata = if (Test-Path -LiteralPath $vetMetadataPath) { Get-Content -LiteralPath $vetMetadataPath -Raw | ConvertFrom-Json } else { $null }
$downloads = @(Get-ChildItem -LiteralPath $treatment -Filter 'download-*-metadata.json' | ForEach-Object { Get-Content -LiteralPath $_.FullName -Raw | ConvertFrom-Json })
$shards = @(Get-ChildItem -LiteralPath $treatment -Filter 'shard-*' -Directory | ForEach-Object {
    $path = Join-Path $_.FullName 'shard-metadata.json'
    if (Test-Path -LiteralPath $path) { Get-Content -LiteralPath $path -Raw | ConvertFrom-Json }
})
$maxDownload = if ($downloads.Count -gt 0) { ($downloads | Measure-Object durationSeconds -Maximum).Maximum } else { $null }
$maxShard = if ($shards.Count -gt 0) { ($shards | Measure-Object durationSeconds -Maximum).Maximum } else { $null }
$compilePath = if ($null -ne $compileMetadata -and $null -ne $maxDownload -and $null -ne $maxShard) {
    [double] $compileMetadata.durationSeconds + [double] $compileMetadata.artifactUploadDurationSeconds + [double] $maxDownload + [double] $maxShard
} else { $null }
$criticalCandidates = @($compilePath)
if ($null -ne $otherMetadata) { $criticalCandidates += [double] $otherMetadata.durationSeconds }
if ($null -ne $vetMetadata) { $criticalCandidates += [double] $vetMetadata.durationSeconds }
$criticalPath = if (@($criticalCandidates | Where-Object { $null -ne $_ }).Count -gt 0) { ($criticalCandidates | Measure-Object -Maximum).Maximum } else { $null }

$driverMetadata = [ordered]@{
    schema = 'ci-bench.a2-treatment.v1'
    label = $label
    randomizedOrderIndex = $control.orderIndex
    shardCount = $shardCount
    repositorySha = $productSha
    goVersion = (& go env GOVERSION).Trim()
    goos = 'windows'
    goarch = 'amd64'
    cgoEnabled = '1'
    cacheSeedManifest = (Join-Path $resultRoot 'cache-seed-manifest.json')
    startTimeUtc = $treatmentStart.ToString('o')
    endTimeUtc = [DateTimeOffset]::UtcNow.ToString('o')
    orchestrationWallSeconds = [math]::Round($treatmentWatch.Elapsed.TotalSeconds, 6)
    modeledCriticalPathSeconds = if ($null -eq $criticalPath) { $null } else { [math]::Round([double] $criticalPath, 6) }
    compileArtifactShardPathSeconds = if ($null -eq $compilePath) { $null } else { [math]::Round([double] $compilePath, 6) }
    longestShardSeconds = $maxShard
    longestArtifactDownloadSeconds = $maxDownload
    otherPackagesSeconds = if ($null -eq $otherMetadata) { $null } else { $otherMetadata.durationSeconds }
    strengthenedVetSeconds = if ($null -eq $vetMetadata) { $null } else { $vetMetadata.durationSeconds }
    verifierExitCode = $verifierExitCode
    exitCode = $finalExitCode
    processSemantics = 'Dynamic listing runs TestMain/init once per heavy package; execution runs TestMain/init once per package per shard, while every top-level test remains assigned exactly once.'
    errors = $driverErrors
}
Write-Json -Path (Join-Path $treatment 'treatment-metadata.json') -Value $driverMetadata

$resultZip = Join-Path $root ($label + '.zip')
if (Test-Path -LiteralPath $resultZip) { Remove-Item -LiteralPath $resultZip -Force }
Compress-Archive -Path (Join-Path $treatment '*') -DestinationPath $resultZip -CompressionLevel Optimal
try {
    Put-Blob -Uri "https://$storageAccount.blob.core.windows.net/results/$label.zip" -Path $resultZip
}
catch {
    $driverErrors.Add("result export failed: $($_.Exception.Message)")
    $finalExitCode = 2
    $driverMetadata.exitCode = $finalExitCode
    $driverMetadata.errors = $driverErrors
    Write-Json -Path (Join-Path $treatment 'treatment-metadata.json') -Value $driverMetadata
}

Write-Output "A2 treatment $label ($shardCount shards) completed with exit $finalExitCode; modeled critical path $criticalPath seconds."
exit $finalExitCode

