const p = [
  {step:"Review the pinned plan and validate repository/CI assumptions",status:"completed"},
  {step:"Build and verify the shared Windows/Azure benchmarking harness",status:"completed"},
  {step:"Run first-wave A1 hardware, A2 compile-once sharding, and A3 cross-compile experiments",status:"in_progress"},
  {step:"Run second-wave A4 test-binary split, A5 Azure hardware/storage, and A6 runtime tuning experiments",status:"pending"},
  {step:"Synthesize results and run the five-repetition champion benchmark",status:"pending"},
  {step:"Prepare the production-ready draft PR and clean all tagged Azure resources",status:"pending"}
]; const r=await tools.update_plan({explanation:"The shared harness is committed and smoke-validated. A1–A3 are running accepted measurements after closing driver, encoding, package-multiplicity, and cross-runtime fidelity gaps.",plan:p}); text(r);

