        -PlanPath $plans[[int] $winner.shardCount] -ManifestRecord $manifests[$index])) | Out-Null
}

$testMainMatches = @(Get-ChildItem -LiteralPath $repo -Recurse -Filter '*_test.go' |
    Select-String -Pattern '^\s*func\s+TestMain\s*\(')
$audit = [ordered]@{
